-- Initial schema generated by AI assistant
create table public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text not null,
  full_name text,
  role text default 'user',
  credits integer default 10,
  created_at timestamptz default now()
);
alter table public.profiles enable row level security;
create policy "Profiles are editable by everyone" on public.profiles
  for update using (true) with check (true);
create policy "Admins can read" on public.profiles
  for select using ( (auth.jwt() -> 'user_metadata' ->> 'role') = 'admin' or raw_user_meta_data->>'role' = 'admin' );

create table public.documents (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references public.profiles(id),
  title text,
  body text,
  created_at timestamptz default now()
);

create table public.integrations (
  id bigserial primary key,
  user_id uuid references public.profiles(id) on delete cascade,
  provider text,
  access_token text,
  refresh_token text
);
alter table public.integrations enable row level security;

create view public.document_stats as
  select owner_id, count(*) as total from public.documents group by owner_id;

create or replace function public.add_credits(target uuid, amount int)
returns void language plpgsql security definer as $$
begin
  update public.profiles set credits = credits + amount where id = target;
end;
$$;

insert into storage.buckets (id, name, public) values ('user-uploads', 'user-uploads', true);
create policy "Anyone can upload" on storage.objects for insert to anon with check (bucket_id = 'user-uploads');
